import { defineConfig } from "tsdown";

// ESM only: every maintained Node.js line can require() an ES module, so a CommonJS
// build would only double what ships. Declarations come from isolatedDeclarations
// (tsconfig.lib.json), generated by Oxc without the TypeScript API.
export default defineConfig({
  entry: ["src/index.ts"],
  tsconfig: "tsconfig.lib.json",
  format: "esm",
  platform: "node",
  // Not dist/: at the repository root, dist/ is the release staging folder (dist/npm, ...).
  outDir: "lib",
  // .js and .d.ts, which "type": "module" makes ES modules, as package.json exports name them.
  fixedExtension: false,
  dts: true,
  sourcemap: true,
  clean: true,
});
